const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Quebec boundary
  const quebec = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM0_NAME', 'Canada'))
    .filter(ee.Filter.eq('ADM1_NAME', 'Quebec'))
    .geometry();

  // 2. Load MODIS Burned Area product for 2023
  const burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2023-01-01', '2023-12-31')
    .filterBounds(quebec)
    .select('BurnDate');

  // Check if collection is empty
  const collectionSize = burnedArea.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log('No burned area data for Quebec in 2023.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Create composite of all burned areas in 2023
  // BurnDate > 0 indicates burned pixel (day of year when burned)
  const burned2023 = burnedArea.map(function(img) {
    return img.gt(0);
  }).sum().gt(0);

  // 4. Count burned pixels
  const pixelCount = burned2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate');

  const count = pixelCount.getInfo();

  if (count === null || count === undefined) {
    console.log('Calculation failed - no valid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (count === 0) {
    console.log('No burned pixels detected in Quebec for 2023.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate area in hectares
  // Each MODIS pixel = 500m x 500m = 250,000 m² = 25 hectares
  const areaHectares = count * 25;

  console.log(`Burned pixels: ${count}`);
  console.log(`Total burned area: ${areaHectares.toFixed(0)} hectares`);
  console.log(`Threshold: 160,000 hectares`);

  // 6. Final answer
  if (areaHectares >= 160000) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
